#!/usr/bin/env python3"""Life OS Automated Form Filler & Recruiter Email Outreach Engine (Track H)Auto-fills standard application form fields based on Arindam's candidate history.Generates recruiter email drafts requiring explicit Human Approval before sending."""import osimport sysimport jsonimport datetimeWORKSPACE_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))PROFILE_PATH = os.path.join(WORKSPACE_ROOT, ".life-os", "career_ops", "candidate_profile.json")OUTREACH_DIR = os.path.join(WORKSPACE_ROOT, ".life-os", "career_ops", "outreach")def load_profile():    if not os.path.exists(PROFILE_PATH):        return {}    with open(PROFILE_PATH, "r", encoding="utf-8") as f:        return json.load(f).get("candidate", {})def get_application_form_payload(job):    profile = load_profile()    return {        "full_name": profile.get("name", "Arindam Islam"),        "email": profile.get("email", "arindambevan04@gmail.com"),        "phone": profile.get("phone", "+91-8553775736"),        "current_location": "Bangalore, India",        "preferred_locations": ["Bangalore", "Remote"],        "total_experience_years": 7.0,        "current_designation": "Lead - Tech Operations",        "notice_period": "Immediate Joiner (Serving Notice Completed — Ready to join next day once hired)",        "expected_ctc_lpa": 18.0,        "min_ctc_lpa_floor": 16.5,        "highest_qualification": "Technical Diploma in Electronics & Communication Engineering",        "degree_status": "No Bachelor's Degree (7+ Years Equivalent Practical Experience)",        "linkedin_url": "https://www.linkedin.com/in/arindam-islam",        "key_skills": [            "Product Operations", "Tech Operations", "Incident Response (ART 8h -> 3h)",            "Adyen Payment Gateway Migration", "Metabase SQL", "Retool", "Appsmith", "n8n", "A/B Testing"        ],        "job_id": job.get("job_id"),        "company": job.get("company"),        "title": job.get("title")    }def generate_recruiter_email_draft(job):    payload = get_application_form_payload(job)    rec_info = job.get("recruiter_details", {})    rec_name = rec_info.get("name", "Hiring Team")    draft = f"""Subject: Application: {payload['title']} - Arindam Islam (7+ Yrs Product & Tech Ops)Dear {rec_name},I am applying for the {payload['title']} role at {payload['company']}.With over 7 years of hands-on experience leading Product & Tech Operations across enterprise SaaS (Get My Parking) and micro-mobility (Bounce), I have:• Led teams of 20+ operations and technical support engineers across 200+ global client sites.• Reduced Average Incident Resolution Time (ART) from 8+ hours to ~3 hours (96%+ operational efficiency).• Spearheaded zero-downtime payment profile migrations (5000+ customer accounts to Adyen).• Built custom admin/ERP dashboards (Retool, Appsmith, Metabase SQL) and automated SLA workflows.My expected CTC is 18 LPA, and I am based in Bangalore. Attached are my tailored resume and portfolio.Best regards,Arindam IslamPhone: {payload['phone']}LinkedIn: {payload['linkedin_url']}"""    os.makedirs(OUTREACH_DIR, exist_ok=True)    file_path = os.path.join(OUTREACH_DIR, f"email_draft_{job.get('job_id')}.txt")    with open(file_path, "w", encoding="utf-8") as f:        f.write(draft)    return file_path, draftdef main():    print("Form Filler & Recruiter Email Outreach Engine Ready.")if __name__ == "__main__":    main()